#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    char *end1, *end2;
    long a = strtol(argv[1], &end1, 10);
    long b = strtol(argv[2], &end2, 10);
    if (*end1 != '\0' || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    // Check for values that cannot be represented as positive long (LLONG_MIN)
    if (a == LLONG_MIN || b == LLONG_MIN) {
        puts("OVERFLOW");
        return 0;
    }
    long abs_a = llabs(a);
    long abs_b = llabs(b);
    // Range check (absolute value must be <= 1,000,000)
    if (abs_a > 1000000L || abs_b > 1000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (abs_a == 0 && abs_b == 0) {
        puts("gcd=0 lcm=0");
        return 0;
    }
    // Euclidean algorithm for GCD
    long x = abs_a, y = abs_b;
    while (y != 0) {
        long r = x % y;
        x = y;
        y = r;
    }
    long gcd = x;
    // Compute LCM safely: (abs_a / gcd) * abs_b
    long div = abs_a / gcd;
    long lcm;
    if (__builtin_mul_overflow(div, abs_b, &lcm)) {
        puts("OVERFLOW");
        return 0;
    }
    printf("gcd=%ld lcm=%ld\n", gcd, lcm);
    return 0;
}
